svg.script:
const dependencies = JSON.parse(document.getElementById("dependencies").textContent);
const stats = JSON.parse(document.getElementById("stats").textContent);
const XHTML = "http://www.w3.org/1999/xhtml";

const dependents = {};
for (const id in dependencies) {
  dependents[id] ??= [];
  for (const dep of dependencies[id]) {
    (dependents[dep] ??= []).push(id);
  }
}

const elements = {};
for (const el of document.querySelectorAll("[data-package]")) {
  (elements[el.dataset.package] ??= []).push(el);
}

const nameLabel = document.getElementById("hover-name");
const panelBox = document.getElementById("stats-panel");
const panel = panelBox.querySelector(".panel");
const svg = panelBox.ownerSVGElement;

function reach(edges, start) {
  const seen = new Set();
  const stack = [...(edges[start] ?? [])];
  while (stack.length > 0) {
    const id = stack.pop();
    if (seen.has(id)) {
      continue;
    }
    seen.add(id);
    stack.push(...(edges[id] ?? []));
  }
  seen.delete(start);
  return seen;
}

function mark(id, cls) {
  for (const el of elements[id] ?? []) {
    el.classList.add(cls);
  }
}

function unmark(id, cls) {
  for (const el of elements[id] ?? []) {
    el.classList.remove(cls);
  }
}

let selected = null;
let hovered = null;

function showName() {
  const id = hovered ?? selected;
  if (id === null) {
    nameLabel.textContent = "";
    return;
  }
  const name = stats[id]?.name ?? id;
  nameLabel.textContent = name;
}

function hover(id) {
  if (id === hovered) {
    return;
  }
  if (hovered !== null) {
    unmark(hovered, "hovered");
  }
  hovered = id;
  if (hovered !== null) {
    mark(hovered, "hovered");
  }
  showName();
}

function select(id) {
  for (const els of Object.values(elements)) {
    for (const el of els) {
      el.classList.remove("selected", "dependency", "dependent", "both");
    }
  }
  selected = id === selected ? null : id;
  svg.classList.toggle("locked", selected !== null);
  showName();
  if (selected === null) {
    panel.hidden = true;
    return;
  }
  const below = reach(dependencies, selected);
  const above = reach(dependents, selected);
  mark(selected, "selected");
  for (const id of below) {
    mark(id, above.has(id) ? "both" : "dependency");
  }
  for (const id of above) {
    if (!below.has(id)) {
      mark(id, "dependent");
    }
  }
  showPanel(selected, below.size, above.size);
}

function create(tag, cls, text) {
  const el = document.createElementNS(XHTML, tag);
  if (cls) {
    el.className = cls;
  }
  if (text !== undefined) {
    el.textContent = text;
  }
  return el;
}

function format(value) {
  if (value === null || value === undefined || value === "") {
    return "N/A";
  }
  if (typeof value === "number") {
    return Number.isInteger(value) ? String(value) : value.toPrecision(4);
  }
  return String(value);
}

function link(url) {
  if (typeof url !== "string" || !url.startsWith("https://")) {
    return create("span", null, format(url));
  }
  const a = create("a", null, url);
  a.href = url;
  a.target = "_blank";
  a.rel = "noopener noreferrer";
  return a;
}

function row(table, label, value) {
  const tr = create("tr");
  tr.append(create("td", null, label));
  const td = create("td");
  td.append(value instanceof Node ? value : document.createTextNode(format(value)));
  tr.append(td);
  table.append(tr);
}

function showPanel(id, transitiveDependencies, transitiveDependents) {
  const s = stats[id] ?? {};
  const header = create("div", "panel-header");
  header.append(create("span", "panel-title", s.name ?? id));
  const collapse = create("button", null, panel.classList.contains("collapsed") ? "+" : "–");
  collapse.title = "Collapse";
  collapse.addEventListener("click", () => {
    const collapsed = panel.classList.toggle("collapsed");
    collapse.textContent = collapsed ? "+" : "–";
    movePanel(panelBox.x.baseVal.value, panelBox.y.baseVal.value);
  });
  const close = create("button", null, "×");
  close.title = "Close and unlock";
  close.addEventListener("click", () => select(selected));
  header.append(collapse, close);

  const body = create("div", "panel-body");
  const table = create("table");
  row(table, "Name", s.name);
  row(table, "Version", s.version);
  row(table, "ID", s.id ?? id);
  row(table, "PURL", s.purl);
  row(table, "License", s.license);
  row(table, "Dependencies", `${format(s.dependencies)} direct, ${transitiveDependencies} transitive`);
  row(table, "Dependents", `${format(s.dependents)} direct, ${transitiveDependents} transitive`);
  row(table, "Repository", link(s.repo_url));
  row(table, "Anitya", link(s.anitya_url));
  row(table, "Score", "N/A");
  row(table, "Signal coverage", typeof s.coverage === "number" ? `${Math.round(s.coverage * 100)}%` : null);
  body.append(table);
  if ((s.signals ?? []).length > 0) {
    body.append(create("div", "panel-section", "Signals"));
    const signals = create("table", "signals");
    for (const [name, weight, value] of s.signals) {
      row(signals, `${name} (weight ${format(weight)})`, value);
    }
    body.append(signals);
  }
  panel.replaceChildren(header, body);
  panel.hidden = false;
  movePanel(panelBox.x.baseVal.value, panelBox.y.baseVal.value);
}

function toViewBox(event) {
  return new DOMPoint(event.clientX, event.clientY).matrixTransform(svg.getScreenCTM().inverse());
}

function movePanel(x, y) {
  const view = svg.viewBox.baseVal;
  const right = view.x + view.width - panel.offsetWidth;
  const bottom = view.y + view.height - panel.offsetHeight;
  panelBox.x.baseVal.value = Math.max(view.x, Math.min(x, right));
  panelBox.y.baseVal.value = Math.max(view.y, Math.min(y, bottom));
}

let drag = null;

panel.addEventListener("pointerdown", (event) => {
  if (event.button !== 0 || !event.target.closest(".panel-header") || event.target.closest("button")) {
    return;
  }
  const start = toViewBox(event);
  drag = { dx: panelBox.x.baseVal.value - start.x, dy: panelBox.y.baseVal.value - start.y };
  panel.setPointerCapture(event.pointerId);
  panel.classList.add("dragging");
  event.preventDefault();
});

panel.addEventListener("pointermove", (event) => {
  if (drag !== null) {
    const point = toViewBox(event);
    movePanel(point.x + drag.dx, point.y + drag.dy);
  }
});

for (const type of ["pointerup", "pointercancel"]) {
  panel.addEventListener(type, () => {
    drag = null;
    panel.classList.remove("dragging");
  });
}

document.addEventListener("pointerover", (event) => {
  const el = event.target.closest?.("[data-package]");
  hover(el ? el.dataset.package : null);
});

document.documentElement.addEventListener("pointerleave", () => hover(null));

document.documentElement.addEventListener("click", (event) => {
  if (event.target.closest?.(".panel")) {
    return;
  }
  const el = event.target.closest?.("[data-package]");
  select(el === null || el === undefined ? null : el.dataset.package);
});
